-- Phase 1: metadata only. Existing catalog/profile sources and assignments stay intact.
begin;

create table if not exists public.asset_library (
  id text primary key check (id ~ '^[A-Za-z0-9][A-Za-z0-9._:-]{0,159}$'),
  name text not null check (length(btrim(name)) between 1 and 200),
  asset_type text not null check (asset_type in ('avatar','frame','banner','ring','wreath','trophy','item','weapon','resource','deviation','catalog','image')),
  category text not null default '' check (length(category) <= 80),
  file_ref text check (file_ref is null or (
    length(file_ref) <= 512 and file_ref ~* '^assets/.+\.(png|jpe?g|webp|svg)$'
    and position('..' in file_ref) = 0 and file_ref !~ '[[:cntrl:]\\%?#"''<>:;]'
  )),
  catalog_id text references public.catalog_entries(id) on delete restrict,
  status text not null default 'draft' check (status in ('draft','active','inactive','archived')),
  users_available boolean generated always as (status = 'active') stored,
  sort_order integer not null default 0 check (sort_order between -100000 and 100000),
  metadata jsonb not null default '{}'::jsonb check (jsonb_typeof(metadata) = 'object' and octet_length(metadata::text) <= 32768),
  revision integer not null default 1 check (revision > 0),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  -- Historical actor IDs remain audit metadata if an Auth account is deleted.
  -- No cascading asset mutation or revision bypass on account deletion.
  created_by uuid,
  updated_by uuid,
  check (status <> 'active' or file_ref is not null or asset_type in ('ring','wreath','trophy'))
);
create index if not exists asset_library_filter_idx on public.asset_library(asset_type,status,sort_order);
comment on table public.asset_library is 'Central asset metadata. Legacy profile assignments and catalog JSON remain their existing sources in phase 1.';
comment on column public.asset_library.users_available is 'Derived from status: only active is released. Never maintained independently.';

create or replace function private.guard_asset_revision()
returns trigger language plpgsql set search_path = '' as $$
begin
  if TG_OP = 'INSERT' then
    if new.revision <> 1 then raise exception 'Initial asset revision must be 1' using errcode = '23514'; end if;
    new.created_by := auth.uid();
    new.created_at := now();
  else
    if new.id <> old.id or new.created_at <> old.created_at or new.created_by is distinct from old.created_by then
      raise exception 'Asset identity and creation fields are immutable' using errcode = '23514';
    end if;
    if new.revision <> old.revision + 1 then
      raise exception 'Asset revision conflict' using errcode = '23514';
    end if;
  end if;
  new.updated_at := now();
  new.updated_by := auth.uid();
  return new;
end;
$$;
revoke all on function private.guard_asset_revision() from public, anon, authenticated;
drop trigger if exists asset_library_revision on public.asset_library;
create trigger asset_library_revision before insert or update on public.asset_library
for each row execute function private.guard_asset_revision();

alter table public.asset_library enable row level security;
revoke all on public.asset_library from public, anon, authenticated;
grant select on public.asset_library to anon, authenticated;
grant insert (id,name,asset_type,category,file_ref,catalog_id,status,sort_order,metadata,revision) on public.asset_library to authenticated;
grant update (name,asset_type,category,file_ref,catalog_id,status,sort_order,metadata,revision) on public.asset_library to authenticated;
drop policy if exists asset_library_public_read on public.asset_library;
create policy asset_library_public_read on public.asset_library for select to anon using (status = 'active');
drop policy if exists asset_library_member_read on public.asset_library;
create policy asset_library_member_read on public.asset_library for select to authenticated
using (status = 'active' or (select private.has_role_at_least('moderator'::public.app_role)));
drop policy if exists asset_library_editor_insert on public.asset_library;
create policy asset_library_editor_insert on public.asset_library for insert to authenticated
with check ((select private.has_role_at_least('moderator'::public.app_role)) and updated_by = (select auth.uid()));
drop policy if exists asset_library_editor_update on public.asset_library;
create policy asset_library_editor_update on public.asset_library for update to authenticated
using ((select private.has_role_at_least('moderator'::public.app_role)))
with check ((select private.has_role_at_least('moderator'::public.app_role)) and updated_by = (select auth.uid()));
-- No DELETE grant or policy. Deactivation/archive is the normal lifecycle.

