as r(id text,name text,asset_type text,category text,file_ref text,status text,sort_order integer,metadata jsonb)
on conflict (id) do nothing;

-- Read the actual live catalog, including entries added after the original 21-row seed.
-- Unsafe/empty legacy references become drafts; no catalog row is modified.
with source as (
  select id, entry,
    case when length(entry->>'image') <= 512
      and entry->>'image' ~* '^assets/.+\.(png|jpe?g|webp|svg)$'
      and position('..' in entry->>'image') = 0
      and entry->>'image' !~ '[[:cntrl:]\\%?#"''<>:;]'
    then entry->>'image' else null end as file
  from public.catalog_entries
)
insert into public.asset_library (id,name,asset_type,category,file_ref,catalog_id,status,sort_order,metadata)
select 'catalog:' || id, entry->>'name_de',
  case entry->>'category' when 'items' then 'item' when 'weapons' then 'weapon' when 'resources' then 'resource' when 'deviations' then 'deviation' else 'catalog' end,
  entry->>'category', file, id, case when file is null then 'draft' else 'active' end, 1000 + row_number() over (order by id)::integer,
  jsonb_build_object('source','catalog_entries','kind',coalesce(entry->>'kind',''),'tags',coalesce(entry->'tags','[]'::jsonb))
from source on conflict (id) do nothing;

notify pgrst, 'reload schema';
commit;
